--
-- Create function "report"."report_get_daily_brands_revenue"
--
CREATE FUNCTION report.report_get_daily_brands_revenue ()
RETURNS TABLE (platform text, currency_code text, date date, active_users_count numeric, daily_order_count text, daily_revenue_usd text, monthly_cumulative_revenue_usd text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
	WITH ExchangeRates AS (
            SELECT 'PHP' AS currency_code, 0.0177 AS rate_to_usd
            UNION ALL SELECT 'HKD', 0.1277
            UNION ALL SELECT 'VND_1000', 0.0398
        ), SubQuery AS (
            SELECT 
                b.code AS platform,
                bc.currency_code,
                ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date AS date,
                COUNT(DISTINCT p.player_code) AS active_users_count, 
                SUM(p.round_count) AS daily_order_count_raw,
                ROUND(SUM(p.win_loss_amount * er.rate_to_usd), 2) AS daily_revenue_usd_raw,
                SUM(ROUND(SUM(p.win_loss_amount * er.rate_to_usd),2)) OVER (
                    PARTITION BY b.code 
                    ORDER BY ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date ASC
                ) AS monthly_cumulative_revenue_usd
            FROM report.player_aggregates p
            JOIN dbo.brands b ON b.id = p.brand_id
            JOIN dbo.brand_currencies bc ON b.id = bc.brand_id
            LEFT JOIN ExchangeRates er ON bc.currency_code = er.currency_code
            WHERE 
                p.report_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '1 day' + INTERVAL '8 hours'
                AND p.report_date < DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' + INTERVAL '8 hours'
                AND p.bet_amount > 0
                AND b.code NOT IN ('Sky8', 'GPI')
            GROUP BY b.code, bc.currency_code, date
        )

    SELECT 
		CAST('Total' AS text) AS platform,
		CAST('' AS text) AS currency_code,
		(CURRENT_DATE - INTERVAL '1 day')::date AS date,
		SUM(sq.active_users_count) AS active_users_count,
		TO_CHAR(SUM(sq.daily_order_count_raw), 'FM999,999,999,999') AS daily_order_count,
		TO_CHAR(SUM(sq.daily_revenue_usd_raw), 'FM999,999,999,999.99') AS daily_revenue_usd,
		TO_CHAR(SUM(sq.monthly_cumulative_revenue_usd), 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
	FROM SubQuery sq
	WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
	UNION ALL
	SELECT 
		CAST(sq.platform AS text), -- Cast to text
		CAST(sq.currency_code AS text), -- Cast to text
		sq.date,
		sq.active_users_count,
		TO_CHAR(sq.daily_order_count_raw, 'FM999,999,999,999') AS daily_order_count,
		TO_CHAR(sq.daily_revenue_usd_raw, 'FM999,999,999,999.99') AS daily_revenue_usd,
		TO_CHAR(sq.monthly_cumulative_revenue_usd, 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
	FROM SubQuery sq
	WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
	order by 2;
END; 
$plpgsql$;

--
-- Create function "report"."get_registered_players_by_brand"
--
CREATE FUNCTION report.get_registered_players_by_brand (IN brand_code character varying, IN start_date timestamp with time zone, IN end_date timestamp with time zone)
RETURNS TABLE (agent text, host text, player text, real_name text, registered_on timestamp with time zone)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY
    SELECT 
        coalesce(a.username, '')::text AS agent,        -- Coalesce to handle possible NULL values
        coalesce(PIR.host, '')::text AS host,           -- Coalesce to handle possible NULL values
        p.username::text AS player,
        coalesce(p.real_name, '')::text AS real_name,   -- Coalesce to handle possible NULL values
        p.registered_on
    FROM 
        dbo.players p
        LEFT JOIN dbo.agents a ON a.id = p.agent_id
        LEFT JOIN dbo.player_ip_records AS PIR ON p.player_code = PIR.player_code
            AND PIR.ip_type = 1
    WHERE 
        p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code) 
        AND p.registered_on >= start_date 
        AND p.registered_on < end_date
    ORDER BY 
        1 NULLS FIRST, 2, 3; -- Order by agent (NULLS FIRST), host, and player
END;
$plpgsql$;

--
-- Create function "report"."get_promotion_distributions"
--
CREATE FUNCTION report.get_promotion_distributions (IN brand_code character varying, IN start_date timestamp with time zone, IN end_date timestamp with time zone)
RETURNS TABLE (username character varying, promotion_name character varying, promotion_type text, bonus_amount numeric, created_on text, sent_on text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY
    SELECT 
		a.username,
        a.name,
        a.promotion_type,
        a.bonus_amount,
	    to_char(a.created_on + interval '8 hours', 'HH24:MI:SS DD/MM/YYYY') AS created_on,
		COALESCE(to_char(a.sent_on + interval '8 hours', 'HH24:MI:SS DD/MM/YYYY'), '') AS sent_on
	FROM (
        SELECT 
            p.username,
            pm.name,
            pm.promotion_type,
            pd.bonus_amount,
		    pd.created_on,
		    pd.sent_on
        FROM dbo.promotion_distributes pd
        JOIN dbo.promotions pm ON pm.id = pd.promotion_id
        JOIN dbo.players p ON p.player_code = pd.player_code
        WHERE p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
            AND pd.sent_on >= start_date
            AND pd.sent_on <  end_date
        UNION
        SELECT 
            p.username,
            pm.name,
            pb.promotion_type,
            pp.bonus_amount,
		    pb.created_on,
		    pp.sent_on
        FROM dbo.promotion_players pp 
        JOIN dbo.promotion_bonuses pb ON pb.id = pp.promotion_bonus_id
        JOIN dbo.promotions pm ON pm.id = pb.promotion_id
        JOIN dbo.players p ON p.player_code = pp.player_code
        WHERE pb.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
            AND pp.sent_on >=  start_date
            AND pp.sent_on < end_date
    ) a
    ORDER BY a.sent_on DESC;
END;
$plpgsql$;

--
-- Create function "report"."get_players_adjust_amount"
--
CREATE FUNCTION report.get_players_adjust_amount (IN brand_code character varying, IN p_start_date date, IN p_end_date date, IN p_type integer)
RETURNS TABLE (玩家用戶名 text, 公司調帳 numeric, 派發前餘額 numeric, 派發後餘額 numeric, 執行時間 timestamp with time zone, 執行者 text, 描述 text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY
    SELECT 
        p.username::text AS "玩家用戶名", 
        t.amount AS "公司調帳", 
        t.balance - t.amount AS "派發前餘額", 
        t.balance AS "派發後餘額", 
        t.recorded_on AS "執行時間", 
        CASE
            WHEN u.id IS NULL THEN 'System'::text
            ELSE u.username::text
        END AS "執行者", 
        t.description::text AS "描述"
    FROM dbo.transactions AS t
    INNER JOIN dbo.players AS p ON t.player_code = p.player_code
    LEFT JOIN dbo.users AS u ON t.created_by_user_id = u.id
    WHERE t.brand_id = (select id from dbo.brands where code = brand_code)
    AND t.recorded_on >= p_start_date
    AND t.recorded_on < p_end_date
    AND t.type = p_type;
END;
$plpgsql$;

--
-- Create function "report"."get_first_deposited_players_by_brand"
--
CREATE FUNCTION report.get_first_deposited_players_by_brand (IN brand_code character varying, IN start_date timestamp with time zone, IN end_date timestamp with time zone)
RETURNS TABLE (agent text, host text, playername text, daily_deposit_amount numeric, daily_deposit_count integer, first_deposit_on timestamp with time zone)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY
    SELECT 
        coalesce(a.username, '')::text AS agent,
        coalesce(PIR.host, '')::text AS host,
        p.username::text AS playername, 
        pdp.daily_deposit_amount, 
        pdp.daily_deposit_count,
        pdp.first_deposit_on
    FROM 
        dbo.player_daily_payment_statistics pdp
        JOIN dbo.players p ON p.player_code = pdp.player_code
        LEFT JOIN dbo.player_ip_records PIR ON p.player_code = PIR.player_code
            AND PIR.ip_type = 1
        LEFT JOIN dbo.agents a ON a.id = p.agent_id
    WHERE 
        p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
        AND pdp.first_deposit_on >= start_date 
        AND pdp.first_deposit_on < end_date 
    ORDER BY 
        1 NULLS FIRST,
        2,
        3;
END;
$plpgsql$;

