--
-- Create schema "bet"
--
CREATE SCHEMA bet;

--
-- Create function "bet"."game_action_get_valid_game_action_external_ids_old"
--
CREATE FUNCTION bet.game_action_get_valid_game_action_external_ids_old (IN game_provider_id uuid, IN player_code character varying, IN external_round_id character varying, IN game_id integer, IN only_placements boolean)
RETURNS TABLE (ExternalBetId character varying, ExternalTransactionId character varying, ExternalRoundId character varying, ExternalGameActionGroupId character varying, GameActionType smallint, Amount numeric, RecordedOn timestamp with time zone, ExternalReferencedTransactionId character varying, ExternalGameId character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	RETURN QUERY
	select 
		ga.external_bet_id as "ExternalBetId",
		ga.external_transaction_id as "ExternalTransactionId",
		r.external_round_id as "ExternalRoundId",
		ga.external_game_action_group_id as "ExternalGameActionGroupId",
		ga."type" as "GameActionType",
		ga.amount as "Amount",
		ga.recorded_on as "RecordedOn",
		(select g.external_transaction_id from bet.game_actions g where g.id = ga.referenced_game_action_id) as "ExternalReferencedTransactionId",
		(select g.external_id from dbo.games g where g.id = r.game_id) as "ExternalGameId"
	from bet.vw_valid_game_actions ga 
	join bet.rounds r on r.id = ga.round_id 
	where r.external_round_id = $3
	and r.player_code = $2
	and r.game_provider_id = $1
	and r.game_id = $4
	and ($5 = false or ga."type" = 0);
	
END;
$plpgsql$;

--
-- Create function "bet"."game_action_get_valid_game_action_external_ids"
--
CREATE FUNCTION bet.game_action_get_valid_game_action_external_ids (IN game_provider_id uuid, IN player_code character varying, IN external_round_id character varying, IN game_id integer, IN only_placements boolean)
RETURNS TABLE (ExternalBetId character varying, ExternalTransactionId character varying, ExternalRoundId character varying, ExternalGameActionGroupId character varying, GameActionType smallint, Amount numeric, RecordedOn timestamp with time zone, ExternalReferencedTransactionId character varying, ExternalGameId character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
begin
	

	CREATE TEMP TABLE IF NOT EXISTS temp_rounds ON COMMIT drop AS
	select r.id as round_id, r.external_round_id, r.game_id, g.external_id as game_external_id
	from bet.rounds r
	join dbo.games g on r.game_id = g.id
	where r.external_round_id = $3
		and r.player_code = $2
		and r.game_provider_id = $1
		and r.game_id = $4
	order by r.created_on asc
	limit 1;
	
    CREATE TEMP TABLE IF NOT EXISTS temp_game_actions ON COMMIT drop AS
	select 
		ga.id, 
		ga.external_transaction_id, 
		ga.external_game_action_group_id, 
		ga.external_bet_id, 
		ga."type", 
		ga.amount, 
		ga.round_id, 
		ga.recorded_on,
		ga.referenced_game_action_id
	from bet.vw_valid_game_actions ga 
	where ga.round_id = (select round_id from temp_rounds)
	and ($5 = false or ga."type" = 0);

	RETURN QUERY
	with act as (
		select 
			ga1.external_bet_id,
			ga1.external_transaction_id,
			ga1.external_game_action_group_id,
			ga1."type",
			ga1.amount,
			ga1.recorded_on,
			ga2.external_transaction_id as referenced_external_transaction_id,
			ga1.round_id
		from temp_game_actions ga1
		left join temp_game_actions ga2 on ga1.referenced_game_action_id = ga2.id
	)
	select 
	  act.external_bet_id as "ExternalBetId",
	  act.external_transaction_id as "ExternalTransactionId",
	  r.external_round_id as "ExternalRoundId",
	  act.external_game_action_group_id as "ExternalGameActionGroupId",
	  act."type" as "GameActionType",
	  act.amount as "Amount",
	  act.recorded_on as "RecordedOn",
	  act.referenced_external_transaction_id as "ExternalReferencedTransactionId",
	  r.game_external_id as "ExternalGameId"
	from act
	join temp_rounds r on r.round_id = act.round_id
	order by act.recorded_on asc;

END;
$plpgsql$;

--
-- Create function "bet"."game_action_get_game_actions_in_same_round"
--
CREATE FUNCTION bet.game_action_get_game_actions_in_same_round (IN game_provider_id uuid, IN player_code character varying, IN external_round_id character varying, IN game_id integer)
RETURNS TABLE (GameActionId uuid, ReferenceGameActionId uuid, ExternalTransactionId character varying, ExternalGameActionGroupId character varying, Turnover numeric, WinLoss numeric, UnsettledBets numeric, IsClosingRound boolean, ClosingRoundExplicitRequest boolean, Type smallint, RoundId uuid, GameId integer, RoundStatus smallint, ExternalRoundId character varying, Amount numeric, GameActionRecordedOn timestamp with time zone, GameActionSentOn timestamp with time zone, BetType character varying, WalletId uuid, JackpotContribution jsonb)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	set lock_timeout to 3000;
	
	RETURN QUERY
	with round as
	(
		select 
			r.id,
			r.game_id,
			r.status,
			r.external_round_id,
			r.wallet_id,
			r.created_on 
		from bet.rounds r
		where r.external_round_id = $3
		and r.player_code = $2
		and r.game_provider_id = $1
		and r.game_id = $4
		for update
	)
	select 
		ga.id as "GameActionId",
		ga.referenced_game_action_id as "ReferenceGameActionId",
		ga.external_transaction_id as "ExternalTransactionId",
		ga.external_game_action_group_id as "ExternalGameActionGroupId",
		ga.turnover as "Turnover",
		ga.win_loss as "WinLoss",
		ga.unsettled_bets as "UnsettledBets",
		ga.is_closing_round as "IsClosingRound",
		ga.closing_round_explicit_request as "ClosingRoundExplicitRequest",
		ga."type" as "Type",
		r.id as "RoundId",
		r.game_id as "GameId",
		r.status as "RoundStatus",
		r.external_round_id as "ExternalRoundId",
		ga.amount as "Amount",
		ga.recorded_on as "GameActionRecordedOn",
		ga.sent_on as "GameActionSentOn",
		ga.bet_type as "BetType",
		r.wallet_id as "WalletId",
		ga.jackpot_contribution as "JackpotContribution"
	from round r 
	join bet.game_actions ga on ga.round_id = r.id 
	where ga.recorded_on >= (r.created_on - 5 * interval '1 minute')
	order by ga.recorded_on asc;
	
END;
$plpgsql$;

--
-- Create function "bet"."game_action_get_game_actions_by_external_transaction_id"
--
CREATE FUNCTION bet.game_action_get_game_actions_by_external_transaction_id (IN game_provider_id uuid, IN player_code character varying, IN external_transaction_id character varying)
RETURNS TABLE (ExternalBetId character varying, ExternalTransactionId character varying, ExternalRoundId character varying, ExternalGameActionGroupId character varying, GameActionType smallint, Amount numeric, RecordedOn timestamp with time zone, ExternalReferencedTransactionId character varying, ExternalGameId character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	RETURN QUERY
	select 
		ga.external_bet_id as "ExternalBetId",
		ga.external_transaction_id as "ExternalTransactionId",
		r.external_round_id as "ExternalRoundId",
		ga.external_game_action_group_id as "ExternalGameActionGroupId",
		ga."type" as "GameActionType",
		ga.amount as "Amount",
		ga.recorded_on as "RecordedOn",
		(select g.external_transaction_id from bet.game_actions g where g.id = ga.referenced_game_action_id) as "ExternalReferencedTransactionId",
		(select g.external_id from dbo.games g where g.id = r.game_id) as "ExternalGameId"
	from bet.game_actions ga 
	join bet.rounds r on r.id = ga.round_id 
	where ga.external_transaction_id = $3
	and r.game_provider_id = $1
	and r.player_code = $2;
	
END;
$plpgsql$;

