--
-- Create function "bet"."game_action_referenced_game_action_exists"
--
CREATE FUNCTION bet.game_action_referenced_game_action_exists (IN game_provider_id uuid, IN player_code character varying, IN external_transaction_id character varying, IN external_round_id character varying)
RETURNS TABLE ("Exists" boolean)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	RETURN QUERY
	select 
		CASE WHEN count(1) > 0 THEN true ELSE false END as "Exists"
	from bet.game_actions ga 
	join bet.rounds r on r.id = ga.round_id 
	where r.external_round_id = $4
	and r.game_provider_id = $1
	and r.player_code = $2
	and ga.external_transaction_id = $3;
	
END;
$plpgsql$;

--
-- Create view "bet"."vw_valid_game_actions"
--
CREATE VIEW bet.vw_valid_game_actions
AS
	SELECT ga.id,
    ga.external_transaction_id,
    ga.type,
    ga.round_id,
    ga.referenced_game_action_id,
    ga.game_action_batch_id,
    ga.recorded_on,
    ga.external_bet_id,
    ga.sent_on,
    ga.player_ip,
    ga.turnover,
    ga.win_loss,
    ga.unsettled_bets,
    ga.is_closing_round,
    ga.closing_round_explicit_request,
    ga.amount,
    ga.external_game_action_group_id,
    ga.balance,
    ga.bet_type,
    ga.extra_data
   FROM bet.game_actions ga
  WHERE ga.type <> 5 AND NOT (EXISTS ( SELECT 1
           FROM bet.game_actions ref
          WHERE ref.type = 5 AND ref.referenced_game_action_id = ga.id AND ref.round_id = ga.round_id AND NOT (EXISTS ( SELECT 1
                   FROM bet.game_actions cancel
                  WHERE cancel.type = 5 AND cancel.referenced_game_action_id = ref.id AND cancel.round_id = ref.round_id))));

