  created_on timestamp with time zone NOT NULL,
  updated_on timestamp with time zone NOT NULL
);

--
-- Create function "dbo"."wallet_update_wallet_balance"
--
CREATE FUNCTION dbo.wallet_update_wallet_balance (IN player_code character varying, IN wallet_id uuid, IN amount numeric, IN updated_on timestamp with time zone)
RETURNS numeric
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
DECLARE 
    updatedCount int;
    bal decimal;
BEGIN
    
    SET LOCK_TIMEOUT TO 3000;
    
    UPDATE dbo.wallets w
    SET 
        balance = w.balance + $3,
        updated_on = $4
    WHERE 
        w.id = $2 
        AND 
        w.player_code = $1
    RETURNING balance INTO bal;

    GET diagnostics updatedCount = ROW_COUNT;

    IF updatedCount = 0 THEN
        RAISE EXCEPTION 'wallet not found.' USING ERRCODE = '5000';
    END IF;
    
    RETURN bal;
    
END;
$plpgsql$;

--
-- Create function "dbo"."report_get_round_and_set_game_setting_aggregates"
--
CREATE FUNCTION dbo.report_get_round_and_set_game_setting_aggregates (IN _from timestamp with time zone, IN _to timestamp with time zone)
RETURNS TABLE (RoundId uuid, PlayerCode text, Turnover numeric, EffectiveBettingPercentage numeric)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
	BEGIN
		RETURN QUERY
		WITH rounds AS(
		select
		r.id "round_id",
		r.player_code,
		r.turnover,
		coalesce(bg.effective_betting_percentage, 100.0) AS effective_betting_percentage
		from bet.rounds r
		left join dbo.brand_games bg on bg.brand_id = r.brand_id and bg.game_id = r.game_id
		where r.closed_on >= _from and r.closed_on < _to and r.reopened_on is null
		and r.effective_betting_percentage is null
		),
		update_rounds as (
		  UPDATE bet.rounds r SET effective_betting_percentage = br.effective_betting_percentage
		  FROM rounds br where r.id = br.round_id
		)

		select
		round_id "RoundId",
		player_code "PlayerCode",
		turnover "Turnover",
		effective_betting_percentage "EffectiveBettingPercentage"
		from rounds;

	END;
	$plpgsql$;

--
-- Create function "dbo"."report_get_round_aggregates"
--
CREATE FUNCTION dbo.report_get_round_aggregates (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _report_date timestamp with time zone, IN _hour integer, IN _minute integer)
RETURNS TABLE (BrandId uuid, AgentId uuid, GameProviderId uuid, PlayerCode character varying, GameType smallint, Username character varying, Hour integer, Minute integer, BetAmount numeric, ValidBetAmount numeric, Turnover numeric, WinLoss numeric, ReportDate timestamp with time zone)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
	select 
	p.brand_id "BrandId",
	p.agent_id "AgentId", 
	g.game_provider_id "GameProviderId",
	p.player_code "PlayerCode", 
	g.type "GameType", 
	p.username "Username", 
	_hour "Hour", 
	_minute "Minute", 
	sum(r.bet_amount) "BetAmount", 
	sum(r.valid_bet_amount) "ValidBetAmount",
	sum(r.turnover) "Turnover", 
	sum(r.win_loss) "WinLoss", 
	_report_date "ReportDate"
    from bet.rounds r 
	join dbo.games g on r.game_id = g.id
	join dbo.players p on r.player_code = p.player_code
    where r.closed_on >= _from and r.closed_on < _to and r.reopened_on is null
	group by p.brand_id, g.game_provider_id, p.player_code, p.agent_id, p.username,g.type;
	
END;
$plpgsql$;

--
-- Create function "dbo"."report_get_player_no_second_deposit_details"
--
CREATE FUNCTION dbo.report_get_player_no_second_deposit_details (IN _brand_id uuid, IN _agent_id uuid, IN _from timestamp with time zone, IN _to timestamp with time zone)
RETURNS TABLE (Username character varying, FirstDepositOn timestamp with time zone, FirstDepositAmount numeric, TotalDepositAmount numeric, TotalWithdrawAmount numeric, DepositSubtractWithdraw numeric, IpAddress character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
WITH depositinterval
     AS (SELECT df.player_code,
                CASE
                  WHEN df.actual_amount IS NULL THEN df.amount
                  ELSE df.actual_amount
                END                          AMOUNT,
                df.created_on,
                COUNT(df.player_code)
                  OVER (
                    partition BY df.player_code) ROWCOUNT
         FROM   dbo.deposit_forms df
		 JOIN   dbo.players p ON p.player_code = df.player_code
         WHERE  df.brand_id = _brand_id
                AND p.agent_id = _agent_id
                AND df.status = 8000
                ),
     totaldeposit
     AS (SELECT T.player_code,
                T.amount,
                T.created_on,
		        T.amount TOTAL_DEPOSIT
         FROM   depositinterval T
         WHERE  ROWCOUNT = 1 
		        AND t.created_on >= _from
                AND t.created_on < _to),
     totalwithdraw
     AS (SELECT T3.*,
                COALESCE(Sum(CASE
                               WHEN W.actual_amount IS NULL THEN W.amount
                               ELSE W.actual_amount
                             END), 0) TOTAL_WITHDRAW
         FROM   totaldeposit T3
                LEFT JOIN dbo.withdraw_forms W
                       ON W.user_id = T3.player_code
                          AND W.status = 9000
         GROUP  BY 1,
                   2,
                   3,
		           4)
SELECT username       AS "Username",
	   created_on     AS "FirstDepositOn",
       amount         AS "FirstDepositAmount",
       total_deposit  AS "TotalDepositAmount",
       total_withdraw AS "TotalWithdrawAmount",
	   total_deposit - total_withdraw AS "DepositSubtractWithdraw",
       ip             AS "IpAddress"
FROM   (SELECT P.username,
               T4.*,
               I.ip,
               Rank()
                 OVER (
                   partition BY I.player_code
                   ORDER BY record_on ASC) IP_RANK
        FROM   totalwithdraw T4
               JOIN dbo.players P
                 ON P.player_code = T4.player_code
               LEFT JOIN dbo.player_ip_records I
                      ON I.player_code = T4.player_code
                         AND ip_type = 1) T5
WHERE  ip_rank = 1 ;
END;
$plpgsql$;

--
-- Create function "dbo"."report_get_player_first_deposit_details"
--
CREATE FUNCTION dbo.report_get_player_first_deposit_details (IN _brand_id uuid, IN _agent_id uuid, IN _from timestamp with time zone, IN _to timestamp with time zone)
RETURNS TABLE (Username character varying, FirstDepositOn timestamp with time zone, FirstDepositAmount numeric, TotalDepositAmount numeric, TotalWithdrawAmount numeric, DepositSubtractWithdraw numeric, IpAddress character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
WITH depositinterval
     AS (SELECT df.player_code,
                CASE
                  WHEN df.actual_amount IS NULL THEN df.amount
                  ELSE df.actual_amount
                END                          AMOUNT,
                df.created_on,
                Row_number()
                  OVER (
                    partition BY df.player_code
                    ORDER BY df.created_on ASC) ROW_NUM
         FROM   dbo.deposit_forms df
		 JOIN   dbo.players p ON p.player_code = df.player_code
         WHERE  df.brand_id = _brand_id
                AND p.agent_id = _agent_id
                AND df.status = 8000
                AND df.created_on >= _from
                AND df.created_on < _to),
     checkfirstdeposit
     AS (SELECT T.player_code,
                T.amount,
                T.created_on,
                Count(d) BEFORE_COUNT
         FROM   depositinterval T
                LEFT JOIN dbo.deposit_forms D
                       ON D.player_code = T.player_code
                          AND D.created_on < _from
                          AND D.status = 8000
         WHERE  row_num = 1
         GROUP  BY 1,
                   2,
                   3),
     totaldeposit
     AS (SELECT T2.player_code,
                T2.amount,
                T2.created_on,
                Sum(D2.amount) TOTAL_DEPOSIT
         FROM   checkfirstdeposit T2
                LEFT JOIN dbo.deposit_forms D2
                       ON D2.player_code = T2.player_code
                          AND D2.status = 8000
         WHERE  before_count = 0
         GROUP  BY 1,
                   2,
                   3),
     totalwithdraw
     AS (SELECT T3.*,
                COALESCE(Sum(CASE
                               WHEN W.actual_amount IS NULL THEN W.amount
                               ELSE W.actual_amount
                             END), 0) TOTAL_WITHDRAW
         FROM   totaldeposit T3
                LEFT JOIN dbo.withdraw_forms W
                       ON W.user_id = T3.player_code
                          AND W.status = 9000
         GROUP  BY 1,
                   2,
                   3,
                   4)
SELECT username       AS "Username",
	   created_on     AS "FirstDepositOn",
       amount         AS "FirstDepositAmount",
       total_deposit  AS "TotalDepositAmount",
       total_withdraw AS "TotalWithdrawAmount",
	   total_deposit - total_withdraw AS "DepositSubtractWithdraw",
       ip             AS "IpAddress"
FROM   (SELECT P.username,
               T4.*,
               I.ip,
               Rank()
                 OVER (
                   partition BY I.player_code
                   ORDER BY record_on ASC) IP_RANK
        FROM   totalwithdraw T4
               JOIN dbo.players P
                 ON P.player_code = T4.player_code
               LEFT JOIN dbo.player_ip_records I
                      ON I.player_code = T4.player_code
                         AND ip_type = 1) T5
WHERE  ip_rank = 1 ;
END;
$plpgsql$;

--
-- Create function "dbo"."report_get_player_account_change_records"
--
CREATE FUNCTION dbo.report_get_player_account_change_records (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _player_code character varying, IN _transaction_type integer DEFAULT NULL::integer, IN _game_action_type integer DEFAULT NULL::integer, IN _page_size integer DEFAULT 10, IN _page_number integer DEFAULT 1)
RETURNS TABLE (TransactionId uuid, GameActionId uuid, Amount numeric, Balance numeric, TransactionType smallint, GameActionType smallint, RecordedOn timestamp with time zone, TotalCount bigint, Description text, ExternalTransactionId text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
	SELECT 
	TRANSACTION_ID as "TransactionId",
	GAME_ACTION_ID as "GameActionId",
	AMOUNT as "Amount",
	BALANCE as "Balance",
	TRANSACTION_TYPE as "TransactionType",
	GAME_ACTION_TYPE as "GameActionType",
	RECORDED_ON as "RecordedOn",
	count(*) over() as "TotalCount",
	DESCRIPTION as "Description",	
	EXTERNAL_TRANSACTION_ID as "ExternalTransactionId"
FROM
				(SELECT ID AS TRANSACTION_ID,
						NULL AS GAME_ACTION_ID,
						AMOUNT,
						BALANCE,
						TYPE AS TRANSACTION_TYPE,
						NULL AS GAME_ACTION_TYPE,
						RECORDED_ON,
						DESCRIPTION,
						EXTERNAL_TRANSACTION_ID
					FROM DBO.TRANSACTIONS
					WHERE RECORDED_ON >= _from
									AND RECORDED_ON < _to
									AND (
											(case 
											 when _transaction_type = 0 then ("type" in (0, 1100))
											 when _transaction_type = 1 then ("type" in (1, 2100))
											 when _transaction_type = 9 then ("type" in (9,2300))
											 when _transaction_type IS null then "type" != 2200
											 else
											 "type" = _transaction_type
									         end) AND _game_action_type IS null)
									AND PLAYER_CODE = _player_code
					UNION ALL SELECT NULL AS TRANSACTION_ID,
						ID AS GAME_ACTION_ID,
						AMOUNT,
						BALANCE,
						NULL AS TRANSACTION_TYPE,
						TYPE AS GAME_ACTION_TYPE,
						RECORDED_ON,
						NULL as DESCRIPTION,
						NULL as EXTERNAL_TRANSACTION_ID
					FROM BET.GAME_ACTIONS
					WHERE RECORDED_ON >= _from
									AND RECORDED_ON < _to
									AND ((_game_action_type IS NULL
														OR "type" = _game_action_type) AND _transaction_type IS NULL)
									AND PLAYER_CODE = _player_code) AS A
ORDER BY A.RECORDED_ON DESC
OFFSET (_page_number-1) * _page_size
LIMIT _page_size;
	
END;
$plpgsql$;

--
-- Create function "dbo"."report_generate_round_aggregates"
--
CREATE FUNCTION dbo.report_generate_round_aggregates (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _report_date timestamp with time zone, IN _created_on timestamp with time zone, IN _hour integer, IN _minute integer)
RETURNS TABLE (BrandId uuid, AgentId uuid, GameProviderId uuid, PlayerCode character varying, GameId integer, GameType smallint, Username character varying, Hour integer, Minute integer, BetAmount numeric, ValidBetAmount numeric, OriginalTurnover numeric, Turnover numeric, WinLoss numeric, ReportDate timestamp with time zone)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
	BEGIN
	RETURN QUERY
		WITH rounds AS(
		SELECT
		r.id,
		r.bet_amount,
		r.valid_bet_amount,
		r.turnover,
		r.win_loss,
		r.game_id,
		r.player_code,
		r.brand_id,
		r.effective_betting_percentage AS round_effective_betting_percentage,
		bg.effective_betting_percentage AS brand_game_effective_betting_percentage
		FROM bet.rounds r
		left join dbo.brand_games bg on bg.brand_id = r.brand_id and bg.game_id = r.game_id
		WHERE r.closed_on >= _from and r.closed_on < _to and r.reopened_on is null
		)
		,roundRows AS (select
		p.brand_id,
		p.agent_id,
		g.game_provider_id,
		p.player_code,
		g.id "game_id",
		g.type "game_type",
		p.username,
		_hour "hour",
		_minute "minute",
		sum(r.bet_amount) "bet_amount",
		sum(r.valid_bet_amount) "valid_bet_amount",
		sum(r.turnover) "original_turnover",
		sum(CASE 
		WHEN r.round_effective_betting_percentage is not null THEN r.turnover * r.round_effective_betting_percentage / 100
		WHEN r.brand_game_effective_betting_percentage is not null THEN r.turnover * r.brand_game_effective_betting_percentage / 100 
		ELSE r.turnover END) "turnover",
		sum(r.win_loss) "win_loss",
		_report_date "report_date",
		_created_on "created_on",
		count(1) "round_count"
		from rounds r
		join dbo.games g on r.game_id = g.id
		join dbo.players p on r.player_code = p.player_code
		group by p.brand_id, g.game_provider_id, p.player_code, p.agent_id, p.username,g.id,g.type),
		insert_rows AS(
		INSERT INTO report.round_aggregates (brand_id,agent_id,player_code,game_provider_id,game_type,hour,minute,bet_amount,valid_bet_amount,original_turnover,turnover,win_loss,report_date,created_on,game_id,round_count)
		SELECT brand_id,agent_id,player_code,game_provider_id,game_type,hour,minute,bet_amount,valid_bet_amount,original_turnover,turnover,win_loss,report_date,created_on,game_id,round_count
		FROM roundRows
		)

		SELECT
		brand_id "BrandId",
		agent_id "AgentId",
		game_provider_id "GameProviderId",
		player_code "PlayerCode",
		game_id "GameId",
		game_type "GameType",
		username "Username",
		hour "Hour",
		minute "Minute",
		bet_amount "BetAmount",
		valid_bet_amount "ValidBetAmount",
		original_turnover "OriginalTurnover",
		turnover "Turnover",
		win_loss "WinLoss",
		report_date "ReportDate"
		from roundRows;
	END;
	$plpgsql$;

--
-- Create function "dbo"."report_generate_game_provider_aggregate_by_external_closed_on"
--
CREATE FUNCTION dbo.report_generate_game_provider_aggregate_by_external_closed_on (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _game_provider_id uuid, IN _audit_log_id integer, IN _created_on timestamp with time zone)
RETURNS void
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$

	BEGIN
	WITH rounds AS(
		SELECT
		r.game_provider_id,
		r.currency_code,
		date_trunc('hour', r.external_closed_on) report_date,
		COUNT(1) transaction_count,
		COALESCE(SUM(bet_amount), 0) bet_amount,
		COALESCE(SUM(valid_bet_amount), 0) valid_bet_amount,
		COALESCE(SUM(turnover), 0) turnover,
		COALESCE(SUM(win_loss), 0) win_loss,
		COALESCE(SUM(settle_amount), 0) settle_amount,
		COALESCE(SUM(commission), 0) commission
		FROM bet.rounds r
		WHERE r.external_closed_on >= _from and r.external_closed_on < _to and r.game_provider_id = _game_provider_id
		GROUP BY 1,2,3
		),
		insert_rows AS(
		INSERT INTO report.game_provider_aggregates (audit_log_id,game_provider_id,currency_code,transaction_count,bet_amount,valid_bet_amount,turnover,win_loss,settle_amount,commission,report_date,created_on)
		SELECT _audit_log_id,game_provider_id,currency_code,transaction_count,bet_amount,valid_bet_amount,turnover,win_loss,settle_amount,commission,report_date,_created_on
		FROM rounds
		)

   		INSERT INTO report.game_provider_aggregate_records (audit_log_id,game_provider_id,"data",created_on)
		SELECT _audit_log_id,_game_provider_id,(select case when count(1) > 0 then jsonb_agg(rounds) else '[]' end FROM rounds),_created_on;
		
	END;
	$plpgsql$;

--
-- Create function "dbo"."promotion_update_amount_used"
--
CREATE FUNCTION dbo.promotion_update_amount_used (IN _promotion_id uuid, IN _amount numeric)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
DECLARE
    row_count int;
    _old_amount decimal;
    _new_amount decimal;
    _total_amount_limit decimal;
    _unlimited boolean;
BEGIN
    set lock_timeout to 3000;

    update dbo.promotions
    set 
        amount_used = amount_used + _amount
    where 
        id = _promotion_id
        AND
        (
			total_amount_limit > amount_used
			OR
			unlimited > 0
		)
    returning amount_used into _total_amount_limit;

    return _total_amount_limit IS NOT NULL;
END;
$plpgsql$;

--
-- Create function "dbo"."promotion_revert_amount_used"
--
CREATE FUNCTION dbo.promotion_revert_amount_used (IN _promotion_id uuid, IN _amount numeric)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	set lock_timeout to 3000;
	
	update dbo.promotions
	set amount_used = amount_used - _amount
	where id = _promotion_id;
	
	return true;
	
END;
$plpgsql$;

--
-- Create function "dbo"."player_get_player_login_records"
--
CREATE FUNCTION dbo.player_get_player_login_records (IN player_code character varying, IN statuses integer[], IN "from" timestamp with time zone)
RETURNS TABLE (BrandId uuid, PlatformType smallint, Status smallint, CreatedOn timestamp with time zone, ExpiredOn timestamp with time zone)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
begin

	RETURN QUERY		
	select
		plr.brand_id as "BrandId",
		plr.platform_type as "PlatformType",
		plr.status as "Status",
		plr.created_on as "CreatedOn",
		plr.expired_on as "ExpiredOn"
	from dbo.player_login_records plr
	where plr.player_code  = $1
	and plr.created_on  >= $3
	and plr.status = any($2);

END;
$plpgsql$;

--
-- Create function "dbo"."player_get_player_for_cache"
--
CREATE FUNCTION dbo.player_get_player_for_cache (IN player_code character varying)
RETURNS TABLE (BrandId uuid, Type smallint, Username character varying, Status smallint, DefaultWalletId uuid, BetLimitId integer, PlayerCode character varying, BrandCode character varying, DefaultWalletCurrencyCode character varying, ExternalCurrencyCode character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
begin

	RETURN QUERY	
	with player as
	(
		select 			
			p.brand_id,
			p."type",
			p.username ,
			p.status ,
			p.default_wallet_id ,
			p.bet_limit_id ,
			p.player_code 			
		from dbo.players p
		where p.player_code = $1
	)
	select
		p.brand_id as "BrandId",
		p."type" as "Type",
		p.username as "Username",
		p.status as "Status",
		p.default_wallet_id as "DefaultWalletId" ,
		p.bet_limit_id as "BetLimitId" ,
		p.player_code as "PlayerCode", 		
		b.code as "BrandCode",
		w.currency_code AS "DefaultWalletCurrencyCode",
		w.external_currency_code as "ExternalCurrencyCode"
	from player p
	join dbo.brands b on  b.id = p.brand_id
	join dbo.wallets w on w.id = p.default_wallet_id;
  
END;
$plpgsql$;

--
-- Create function "dbo"."localization_get_localization_by_game_provider_id"
--
CREATE FUNCTION dbo.localization_get_localization_by_game_provider_id (IN game_provider_id uuid)
RETURNS TABLE (Context character varying, Key character varying, CultureCode character varying, Transalation character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
begin

	drop table if exists contexts cascade;
    
	create temp table contexts as 
	select id::varchar as "value" 
	from dbo.games g
    where g.game_provider_id = $1
    union
	select $1::varchar;

	return QUERY
    select distinct 
        ls.context as "Context",
        ls."key" as "Key",
        ls.culture_code as "CultureCode",
        ls."translation" as "Transalation"
    from dbo.localized_strings ls 
    join contexts ct on ls."key" = ct."value";
  
END;
$plpgsql$;

