CREATE FUNCTION dbo.brand_get_brand_for_cache (IN brand_id uuid)
RETURNS TABLE (Id uuid, Code character varying, Name character varying, TimeZoneId character varying, Status smallint, ClientId character varying, SecretKey character varying, LicenseeId uuid, LicenseeCode character varying, ResellerId uuid, ResellerCode character varying)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
	
	RETURN QUERY	
	with brand as
	(
		select 			
			id,
			time_zone_id,
			code,
			"name",
			status,
			client_id,
			secret_key,
			licensee_id
		from dbo.brands
		where id = $1
	)
	select
		b.id as "Id",
		b.code as "Code",
		b."name" as "Name",
		b.time_zone_id as "TimeZoneId",
		b.status as "Status",		
		b.client_id as "ClientId",
		b.secret_key as "SecretKey",
		l.id AS "LicenseeId",
		l.code AS "LicenseeCode",
		r.id AS "ResellerId",
		r.code AS "ResellerCode"		
	from brand b
	join dbo.licensees l on l.id = b.licensee_id
	join dbo.resellers r on r.id = l.reseller_id;
END;
$plpgsql$;

--
-- Create function "dbo"."brand_game_providers_status_changes"
--
CREATE FUNCTION dbo.brand_game_providers_status_changes (IN _to_maintenance_text text, IN _to_active_text text)
RETURNS void
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
declare
	to_maintenance_ids uuid[];
	to_active_ids uuid[];
BEGIN

    to_maintenance_ids = string_to_array(_to_maintenance_text,',');
	to_active_ids = string_to_array(_to_active_text,',');
	
    update dbo.brand_game_providers
    set status = 3 where id = ANY(to_maintenance_ids);

	update dbo.brand_game_providers
    set status = 0 where id = ANY(to_active_ids);

END;
$plpgsql$;

--
-- Create function "dbo"."agent_wallet_update_wallet_balance"
--
CREATE FUNCTION dbo.agent_wallet_update_wallet_balance (IN agent_id uuid, IN wallet_id uuid, IN amount numeric, IN updated_on timestamp with time zone)
RETURNS numeric
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
declare 
	row_count int;
	bal decimal;
BEGIN
	
	set lock_timeout to 3000;
    
    update dbo.agent_wallets w
    set balance = w.balance + $3,
    	updated_on = $4
    where w.id = $2 and w.agent_id = $1
	returning balance into bal;

	get diagnostics row_count = ROW_COUNT;

	if row_count = 0 then
		raise exception 'agent wallet not found.' using ERRCODE = '5000';
	end if;
	
	return bal;
	
END;
$plpgsql$;

--
-- Create function "dbo"."agent_get_all_sub_agents"
--
CREATE FUNCTION dbo.agent_get_all_sub_agents (IN _agent_path text)
RETURNS TABLE (Id uuid, Username character varying, ParentAgentId uuid, Path ltree)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY

	select id "Id",
	username "Username",
	parent_agent_id "ParentAgentId",
	path "Path"
	from dbo.agents where _agent_path::ltree @> path;

END;
$plpgsql$;

--
-- Create function "dbo"."agent_get_agents_with_team_counts"
--
CREATE FUNCTION dbo.agent_get_agents_with_team_counts (IN _brand_id uuid, IN _username text, IN _page_size integer, IN _page_number integer, IN _sort_by text, IN _is_desc boolean, IN _status integer DEFAULT NULL::integer, IN _type integer DEFAULT NULL::integer, IN _level_type integer DEFAULT NULL::integer)
RETURNS TABLE (Id uuid, BrandId uuid, Username character varying, RealName character varying, Status smallint, AgentStatus integer, Type smallint, LevelType integer, Balance numeric, CommissionPercentage numeric, DividendPercentage numeric, LiveDealerRebatePercentage numeric, SlotRebatePercentage numeric, LotteryRebatePercentage numeric, CardGameRebatePercentage numeric, SportsRebatePercentage numeric, VirtualSportsRebatePercentage numeric, TeamNumber numeric, PlayerNumber bigint, TotalCount bigint)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 

	WITH RECURSIVE SUBAGENTS AS (
			SELECT A.ID, 
				   A.ID MAIN_ID,
				   (SELECT COUNT(1) FROM DBO.PLAYERS WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT NULL) PLAYER_COUNT
			FROM DBO.AGENTS A
			WHERE A.BRAND_ID = _brand_id
		UNION 
			SELECT A.ID,
			       S.MAIN_ID,
			       (SELECT COUNT(1) FROM DBO.PLAYERS WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT NULL) PLAYER_COUNT
		    FROM DBO.AGENTS A
			INNER JOIN SUBAGENTS S ON S.ID = A.PARENT_AGENT_ID
			WHERE A.BRAND_ID = _brand_id )
SELECT A.ID as "Id",
	   A.BRAND_ID as "BrandId",
	   A.USERNAME as "Username",
	   A.REAL_NAME  as "RealName",
	   A.STATUS as "Status",
	   A.AGENT_STATUS as "AgentStatus",
	   A.TYPE as "Type",
	   A.LEVEL_TYPE as "LevelType",
	   (SELECT BALANCE FROM DBO.AGENT_WALLETS WHERE AGENT_ID = A.ID) as "Balance",
	A.COMMISSION_PERCENTAGE as "CommissionPercentage",
	A.DIVIDEND_PERCENTAGE as "DividendPercentage",
	A.LIVE_DEALER_REBATE_PERCENTAGE as "LiveDealerRebatePercentage",
	A.SLOT_REBATE_PERCENTAGE as "SlotRebatePercentage",
	A.LOTTERY_REBATE_PERCENTAGE as "LotteryRebatePercentage",
	A.CARD_GAME_REBATE_PERCENTAGE as "CardGameRebatePercentage",
	A.SPORTS_REBATE_PERCENTAGE as "SportsRebatePercentage",
	A.VIRTUAL_SPORTS_REBATE_PERCENTAGE as "VirtualSportsRebatePercentage",
	T.AGENT_COUNT + T.PLAYER_COUNT as "TeamNumber",
	(SELECT COUNT(*) FROM DBO.PLAYERS WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT null) as "PlayerNumber",
	count(*) over() as "TotalCount"
FROM DBO.AGENTS A
INNER JOIN (SELECT G.MAIN_ID,
				COUNT(1) AGENT_COUNT,
				SUM(G.PLAYER_COUNT) PLAYER_COUNT
			FROM
				(SELECT ID,
						MAIN_ID,
						PLAYER_COUNT
				 FROM SUBAGENTS) G
			GROUP BY G.MAIN_ID) T ON A.ID = T.MAIN_ID
WHERE A.BRAND_ID = _BRAND_ID
		AND (_STATUS IS NULL OR A.STATUS = _STATUS)
		AND (_TYPE IS NULL OR A.TYPE = _TYPE)
		AND (_LEVEL_TYPE IS NULL OR A.LEVEL_TYPE = _LEVEL_TYPE)
		AND ((_USERNAME IS NULL OR _USERNAME = '') OR A.USERNAME ilike '%' || _USERNAME || '%')
		order by
	  case when _is_desc = false AND lower(_sort_by) = 'username'	then a.username	end asc,
	  case when _is_desc = false AND lower(_sort_by) = 'status'	then a.status	end asc,
	  case when _is_desc = true AND lower(_sort_by) = 'username'	then a.username	end desc,
	  case when _is_desc = true AND lower(_sort_by) = 'status'		then a.status		end desc
    offset (_page_number-1) * _page_size 
	limit _page_size;
	
END;
$plpgsql$;

