--
-- Create function "dbo"."wallet_get_balance"
--
CREATE FUNCTION dbo.wallet_get_balance (IN wallet_id uuid)
RETURNS numeric
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
declare
	bal decimal;
begin

	select w.balance into bal
	from dbo.wallets w
	where w.id = $1;

	return bal;

END;
$plpgsql$;

