--
-- Create function "dbo"."station_letter_insert_players"
--
CREATE FUNCTION dbo.station_letter_insert_players (IN _brand_id uuid, IN _station_letter_id uuid)
RETURNS void
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN

	insert into dbo.station_letter_players 
	select _station_letter_id, player_code, false, null 
	from dbo.players
	where brand_id = _brand_id
      and status = 0;
	
END;
$plpgsql$;

