  brand_id uuid NOT NULL,
  status smallint NOT NULL,
  platform_type smallint NOT NULL,
  ip_address text,
  created_on timestamp with time zone NOT NULL,
  expired_on timestamp with time zone NOT NULL
);

--
-- Create procedure "dbo"."player_deauthorize_by_platform_type"
--
CREATE PROCEDURE dbo.player_deauthorize_by_platform_type (IN player_code character varying, IN platform_type smallint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $plpgsql$
begin

	update dbo.player_login_records plr
	set status = 1
	where plr.player_code = $1
	and (plr.platform_type = $2 or $2 is null)
	and plr.status = 0
	and plr.expired_on >= now();

END;
$plpgsql$;

--
-- Create procedure "dbo"."player_deauthorize_by_login_record_id"
--
CREATE PROCEDURE dbo.player_deauthorize_by_login_record_id (IN player_code character varying, IN login_record_id uuid)
LANGUAGE plpgsql
SECURITY INVOKER
AS $plpgsql$
begin

	update dbo.player_login_records plr
	set status = 1
	where plr.id = $2
	and plr.player_code = $1
	and plr.status  = 0
	and plr.expired_on >= now();

END;
$plpgsql$;

