--
-- Create function "report"."get_player_withdraw_count"
--
CREATE FUNCTION report.get_player_withdraw_count (IN brand_code character varying, IN start_date date, IN end_date date)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
DECLARE
    withdraw_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO withdraw_count
    FROM (
        SELECT pdps.player_code, COUNT(*) AS cc
        FROM dbo.player_daily_payment_statistics pdps
        JOIN dbo.players p ON p.player_code = pdps.player_code
        JOIN dbo.brands b ON p.brand_id = b.id
        WHERE b.code = brand_code
          AND pdps.report_date >= start_date
          AND pdps.report_date < end_date
          AND pdps.daily_withdraw_amount > 0
        GROUP BY pdps.player_code
    ) a
    WHERE a.cc > 0;
	RETURN withdraw_count;
END;
$plpgsql$;

--
-- Create function "report"."get_bonus_player_count"
--
CREATE FUNCTION report.get_bonus_player_count (IN brand_code character varying, IN start_date timestamp with time zone, IN end_date timestamp with time zone)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
DECLARE
    player_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO player_count
    FROM (
        SELECT 
            player_code,
            SUM(birthday_amount + season_amount + upgrade_amount + promotion_amount + rebate_amount) AS bonus
        FROM 
            report.player_aggregates 
        WHERE 
            brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
            AND report_date >= start_date
            AND report_date < end_date 
        GROUP BY 
            player_code
    ) a 
    WHERE a.bonus > 0;

    RETURN player_count;
END;
$plpgsql$;

