--
-- Create schema "log"
--
CREATE SCHEMA log;

--
-- Create function "log"."log_get_log_records"
--
CREATE FUNCTION log.log_get_log_records (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _tracking_id uuid, IN _server_name text, IN _level integer, IN _page_size integer, IN _page_number integer, IN _sort_by text, IN _is_desc boolean)
RETURNS TABLE (RecordedOn timestamp with time zone, TrackingId uuid, Id uuid, ServerName character varying, Level integer, Logger text, Message text, Exception text, TotalCount bigint)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
	SELECT
        a.recorded_on as RecordedOn, 
        a.tracking_id as TrackingId, 
        a.id as Id,
		a.server_name as ServerName,
		a.level as Level,
		a.logger as Logger,
		a.message as Message,
		a.exception as Exception,
		count(*) OVER() AS TotalCount
    FROM log.log_records a
    WHERE a.recorded_on >= _from        
      AND a.recorded_on < _to  
      AND (_tracking_id IS NULL OR a.tracking_id = _tracking_id)
	  AND (_level IS NULL OR a.level = _level)
	  and ((_server_name is null or _server_name = '') OR a.server_name ilike '%' || _server_name || '%')
    ORDER BY
			CASE WHEN _is_desc = false AND _sort_by = 'RecordedOn'	THEN recorded_on	END ASC,
			CASE WHEN _is_desc = false AND _sort_by = 'Level'		THEN level			END ASC,
			CASE WHEN _is_desc = true AND _sort_by = 'RecordedOn'	THEN recorded_on	END DESC,
			CASE WHEN _is_desc = true AND _sort_by = 'Level'		THEN level			END DESC
    Offset (_page_number-1) * _page_size 
	Limit _page_size;
END
$plpgsql$;

--
-- Create function "log"."log_get_api_logs"
--
CREATE FUNCTION log.log_get_api_logs (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _tracking_id uuid, IN _ip text, IN _path text, IN _method text, IN _prefix text, IN _server_name text, IN _response_code integer, IN _page_size integer, IN _page_number integer, IN _sort_by text, IN _is_desc boolean)
RETURNS TABLE (RecordedOn timestamp with time zone, TrackingId uuid, Id uuid, Ip character varying, Path text, Method character varying, Prefix character varying, ServerName character varying, ResponseCode smallint, ExecutionTimeMs integer, RequestHeaders text, RequestContent text, ResponseHeaders text, ResponseContent text, TotalCount bigint)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN

    RETURN QUERY 
	select
        a.recorded_on as "RecordedOn", 
        a.tracking_id as "TrackingId", 
        a.id as "Id",
        a.ip as "Ip",
        a.path as "Path",
        a.method as "Method",
		a.prefix as "Prefix",
		a.server_name as "ServerName",
		a.response_code as "ResponseCode",
		a.execution_time_ms as "ExecutionTimeMs",
		a.request_headers AS "RequestHeaders",
		a.request_content AS "RequestContent",
		a.response_headers AS "ResponseHeaders",
		a.response_content AS "ResponseContent",
		count(*) over() as "TotalCount"
    from log.api_logs a
    where a.recorded_on >= _from        
      and a.recorded_on < _to  
      and (_tracking_id is null or a.tracking_id = _tracking_id)
	  and (_ip is null or a.ip = _ip)
      and ((_path is null or _path = '') or a.path ilike '%' || _path || '%')
	  and ((_prefix is null or _prefix = '') or a.prefix ilike '%' || _prefix || '%')
	  and ((_server_name is null or _server_name = '') or a.server_name ilike '%' || _server_name || '%')
      and (_method is null or a.method = _method)    
      and (_response_code is null or a.response_code = _response_code)    
    order by
			case when _is_desc = false AND _sort_by = 'RecordedOn'	then a.recorded_on	end asc,
			case when _is_desc = false AND _sort_by = 'Method'		then a.method		end asc,
			case when _is_desc = false AND _sort_by = 'Ip'			then a.ip			end asc,
			case when _is_desc = false AND _sort_by = 'Path'		then a.path			end asc,
			case when _is_desc = true AND _sort_by = 'RecordedOn'	then a.recorded_on	end desc,
			case when _is_desc = true AND _sort_by = 'Method'		then a.method		end desc,
			case when _is_desc = true AND _sort_by = 'Ip'			then a.ip			end desc,
			case when _is_desc = true AND _sort_by = 'Path'			then a.path			end desc
    offset (_page_number-1) * _page_size 
	limit _page_size;
END;
$plpgsql$;

--
-- Create function "log"."log_get_api_log"
--
CREATE FUNCTION log.log_get_api_log (IN tracking_id uuid)
RETURNS TABLE (RequestHeaders text, RequestContent text, ResponseHeaders text, ResponseContent text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN

    RETURN QUERY
    select
		a.request_headers AS "RequestHeaders",
		a.request_content AS "RequestContent",
		a.response_headers AS "ResponseHeaders",
		a.response_content AS "ResponseContent"
    from log.api_logs a
    where a.tracking_id = $1;

END;
$plpgsql$;

--
-- Create function "log"."log_get_admin_logs"
--
CREATE FUNCTION log.log_get_admin_logs (IN _from timestamp with time zone, IN _to timestamp with time zone, IN _tracking_id uuid, IN _ip text, IN _path text, IN _method text, IN _server_name text, IN _response_code integer, IN _page_size integer, IN _page_number integer, IN _sort_by text, IN _is_desc boolean)
RETURNS TABLE (RecordedOn timestamp with time zone, TrackingId uuid, Id uuid, Ip character varying, Path character varying, Method character varying, Description character varying, Exception text, StackTrace text, InnerException text, ServerName character varying, ResponseCode smallint, ExecutionTimeMs integer, RequestHeaders text, RequestContent text, ResponseHeaders text, ResponseContent text, TotalCount bigint)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN
    RETURN QUERY 
	select
        a.recorded_on as "RecordedOn", 
        a.tracking_id as "TrackingId", 
        a.id as "Id",
        a.ip as "Ip",
        a.path as "Path",
        a.method as "Method",
        a.description as "Description",
		a.exception as "Exception",
		a.stack_trace as "StackTrace",
		a.inner_exception as "InnerException",
		a.server_name as "ServerName",
		a.response_code as "ResponseCode",
		a.execution_time_ms as "ExecutionTimeMs",
		a.request_headers AS "RequestHeaders",
		a.request_content AS "RequestContent",
		a.response_headers AS "ResponseHeaders",
		a.response_content AS "ResponseContent",
		count(*) over() as "TotalCount"
    from log.admin_logs a
    where a.recorded_on >= _from        
      and a.recorded_on < _to  
      and (_tracking_id is null or a.tracking_id = _tracking_id)
	  and (_ip is null or a.ip = _ip)
      and ((_path is null or _path = '') OR a.path ilike '%' || _path || '%')
	  and ((_server_name is null or _server_name = '') OR a.server_name ilike '%' || _server_name || '%')
      and (_method is null or a.method = _method) 
	  and (_response_code is null or a.response_code = _response_code)
    order by
			case when _is_desc = false AND _sort_by = 'RecordedOn'	then a.recorded_on	end asc,
			case when _is_desc = false AND _sort_by = 'Method'		then a.method		end asc,
			case when _is_desc = false AND _sort_by = 'Ip'			then a.ip			end asc,
			case when _is_desc = false AND _sort_by = 'Path'		then a.path			end asc,
			case when _is_desc = true AND _sort_by = 'RecordedOn'	then a.recorded_on	end desc,
			case when _is_desc = true AND _sort_by = 'Method'		then a.method		end desc,
			case when _is_desc = true AND _sort_by = 'Ip'			then a.ip			end desc,
			case when _is_desc = true AND _sort_by = 'Path'			then a.path			end desc
    offset (_page_number-1) * _page_size 
	limit _page_size;

END;
$plpgsql$;

--
-- Create function "log"."log_get_admin_log"
--
CREATE FUNCTION log.log_get_admin_log (IN tracking_id uuid)
RETURNS TABLE (RequestHeaders text, RequestContent text, ResponseHeaders text, ResponseContent text)
LANGUAGE plpgsql
VOLATILE
AS $plpgsql$
BEGIN

    RETURN QUERY
    select
		a.request_headers AS "RequestHeaders",
		a.request_content AS "RequestContent",
		a.response_headers AS "ResponseHeaders",
		a.response_content AS "ResponseContent"
    from log.admin_logs a
    where a.tracking_id = $1;

END;
$plpgsql$;

